// Meta webhook verification (GET). Meta sends hub.mode, hub.verify_token and hub.challenge as query parameters.
// The expected token comes from the "W2 – Verify Config" node (a placeholder you fill in); it is never written in this code
// and it is NOT copied into this node's output.
const q = $json.query || {};
const pick = (k) => {
  const v = q['hub.' + k] !== undefined ? q['hub.' + k] : (q.hub && q.hub[k]);   // n8n keeps "hub.mode" as one key; a nested hub{} is handled too
  return Array.isArray(v) ? String(v[0]) : (v === undefined || v === null ? '' : String(v));
};
const mode = pick('mode');
const sent = pick('verify_token');
const challenge = pick('challenge');
const want = String($json.meta_verify_token || '');
const PLACEHOLDER = 'PASTE_META_WEBHOOK_VERIFY_TOKEN';
const same = (a, b) => {                                  // compares every character, so the time taken does not reveal how much matched
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
};

let ok = false;
let status = 403;
let reason = '';
if (!want || want === PLACEHOLDER) reason = 'verify token is not configured (fill it in the "W2 – Verify Config" node)';
else if (mode !== 'subscribe') reason = 'hub.mode is not "subscribe"';
else if (!same(sent, want)) reason = 'verify token does not match';
else if (!/^[0-9A-Za-z_.~-]{1,128}$/.test(challenge)) { reason = 'hub.challenge is missing or malformed'; status = 400; }
else ok = true;

return { json: { ok, status_code: ok ? 200 : status, challenge: ok ? challenge : '', reason } };

// Manual test data for W2. Click "Execute workflow" on "W2 – Manual Test": every case below goes through the normal path
// (Config -> Parse -> clinic -> duplicate check -> lead -> conversation -> message -> Run_Log) WITHOUT Meta and without answering a webhook.
// SAFE FAKE DATA ONLY: the 91900000001x numbers and the display number 15550000000 are made up. Never paste a real patient's number here.
//
// Before the first run create ONE test lead in the demo-clinic CRM:  Phone +919000000011,  Name "W2 Test Existing".
// Afterwards delete the rows the tests created (leads, conversations, messages, Run_Log) by hand in Grist: W2 never deletes anything.
const DEMO_PHONE_NUMBER_ID = '123456789012345';   // WA_Phone_Number_ID of demo-clinic in the Agency Registry
const ONLY = '';              // a case name (e.g. 'new-patient') runs just that one; '' runs all of them
const PASTED_PAYLOAD = null;  // or paste ONE Meta POST body here (a JSON object) to run only that payload
const stamp = Date.now();     // makes the message ids unique for every run of this node (the duplicate case reuses one id on purpose)
const EXISTING = '919000000011';
const NEW_PATIENT = '919000000012';

const meta = (pid, name, from, message) => ({
  object: 'whatsapp_business_account',
  entry: [{ id: 'TEST_WABA_ID', changes: [{ field: 'messages', value: {
    messaging_product: 'whatsapp',
    metadata: { display_phone_number: '15550000000', phone_number_id: pid },
    contacts: name === null ? [] : [{ profile: { name }, wa_id: from }],
    messages: [message],
  } }] }],
});
const ts = String(Math.floor(stamp / 1000));
const text = (from, id, body) => ({ from, id, timestamp: ts, type: 'text', text: { body } });

const cases = [
  { name: 'existing-patient', expect: 'existing lead: NO new lead; 1 new message; conversation updated (Unread +1); Run_Log ok',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test Existing', EXISTING, text(EXISTING, `wamid.W2TEST.${stamp}.existing`, 'Hello, I would like to ask about my knee.')) },
  { name: 'new-patient', expect: 'NEW lead (Source WhatsApp, Status New, Lead_id L-YYYYMMDD-NNNN) + conversation + message; Run_Log ok; staff alert prepared (not sent)',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test New', NEW_PATIENT, text(NEW_PATIENT, `wamid.W2TEST.${stamp}.new`, 'Hi, do you treat back pain?')) },
  { name: 'duplicate-message-first', expect: 'stored once',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test Existing', EXISTING, text(EXISTING, `wamid.W2TEST.${stamp}.dup`, 'Duplicate delivery test')) },
  { name: 'duplicate-message-second', expect: 'SAME message id again: nothing created, Unread not increased, Run_Log skipped (duplicate WA_Message_ID)',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test Existing', EXISTING, text(EXISTING, `wamid.W2TEST.${stamp}.dup`, 'Duplicate delivery test')) },
  { name: 'unknown-phone-number-id', expect: 'stops at "W2 – Clinic Rejected" (unknown phone_number_id); nothing written',
    body: meta('000000000000000', 'W2 Test Existing', EXISTING, text(EXISTING, `wamid.W2TEST.${stamp}.unknown`, 'Unknown clinic test')) },
  { name: 'invalid-payload', expect: 'Parse says kind = invalid; nothing else runs',
    body: { hello: 'this is not a Meta webhook body' } },
  { name: 'non-text-image', expect: 'no crash; Body = "[WhatsApp image received]: photo of my knee"; Enquiry untouched',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test Existing', EXISTING, { from: EXISTING, id: `wamid.W2TEST.${stamp}.image`, timestamp: ts, type: 'image', image: { id: 'TEST_MEDIA_ID', mime_type: 'image/jpeg', sha256: 'test', caption: 'photo of my knee' } }) },
  { name: 'status-event', expect: 'a delivery receipt, not a patient message: ignored, nothing written',
    body: { object: 'whatsapp_business_account', entry: [{ id: 'TEST_WABA_ID', changes: [{ field: 'messages', value: { messaging_product: 'whatsapp', metadata: { display_phone_number: '15550000000', phone_number_id: DEMO_PHONE_NUMBER_ID }, statuses: [{ id: `wamid.W2TEST.${stamp}.status`, status: 'delivered', timestamp: ts, recipient_id: EXISTING }] } }] }] } },
];

const wrap = (name, expect, body) => ({ json: { __w2_source: 'manual', test_case: name, test_expect: expect, headers: {}, params: {}, query: {}, body } });
if (PASTED_PAYLOAD !== null) return [wrap('pasted-payload', 'whatever your payload should do', PASTED_PAYLOAD)];
return cases.filter((c) => !ONLY || c.name === ONLY).map((c) => wrap(c.name, c.expect, c.body));

// Reads the Meta WhatsApp Cloud API webhook body (entry[].changes[].value) and returns ONE envelope item:
//   kind 'message' = at least one inbound patient message (in events[]) | 'status' = delivery receipts only |
//   'ignored' = Meta-shaped but nothing to store | 'invalid' = not a Meta webhook body at all.
// It never throws. headers / query / params are dropped here so they do not travel through the rest of the workflow.
const raw = $json.body;
const source = $json.__w2_source === 'manual' ? 'manual' : 'webhook';   // only the manual-test node can set this (it is a top-level key, not part of the body)
const cfg = {};
for (const [k, v] of Object.entries($json)) {
  if (['headers', 'params', 'query', 'body', 'webhookUrl', 'executionMode'].includes(k) || k.startsWith('__w2')) continue;
  cfg[k] = v;                                                              // Config values (and test_case / test_expect for the manual test)
}
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const noControl = (v) => String(v === null || v === undefined ? '' : v).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '');
const line = (v, max) => noControl(v).replace(/\s+/g, ' ').trim().slice(0, max);
const text = (v, max) => noControl(v).trim().slice(0, max);               // keeps line breaks
const nowSec = Math.floor(Date.now() / 1000);
const MAX_EVENTS = 100;

const events = [];
const rejected = [];
let statuses = 0;

const done = (kind, extra) => ({
  json: {
    ...cfg, source, kind, events, rejected, statuses_seen: statuses,
    http_status: kind === 'invalid' ? 400 : 200,
    response_body: JSON.stringify(kind === 'invalid' ? { status: 'invalid', error: extra } : { status: kind === 'message' ? 'received' : kind }),
    reject_reason: kind === 'invalid' ? extra : rejected.join('; '),
  },
});

if (!isObj(raw) || !Array.isArray(raw.entry)) return done('invalid', 'body is not a Meta webhook payload (entry[] is missing)');

for (const entry of raw.entry) {
  if (!isObj(entry) || !Array.isArray(entry.changes)) continue;
  for (const change of entry.changes) {
    const v = isObj(change) ? change.value : null;
    if (!isObj(v)) continue;
    if (Array.isArray(v.statuses)) statuses += v.statuses.length;
    if (!Array.isArray(v.messages) || !v.messages.length) continue;       // delivery receipts, template updates, ...: not patient messages
    const pid = isObj(v.metadata) ? line(v.metadata.phone_number_id, 40) : '';
    const contacts = Array.isArray(v.contacts) ? v.contacts.filter(isObj) : [];
    for (const m of v.messages) {
      if (events.length >= MAX_EVENTS) { rejected.push(`more than ${MAX_EVENTS} messages in one payload: the rest were ignored`); break; }
      if (!isObj(m)) { rejected.push('a message entry is not an object'); continue; }
      const id = line(m.id, 200);
      const from = line(m.from, 30);
      const problems = [];
      if (!pid) problems.push('missing metadata.phone_number_id');
      if (!id) problems.push('missing message id');
      if (!from) problems.push('missing sender phone');
      if (problems.length) { rejected.push(problems.join(', ')); continue; }

      const type = line(m.type, 30).toLowerCase() || 'unknown';
      const part = isObj(m[type]) ? m[type] : {};
      let label = '';                                                       // what the patient actually wrote, when there is text
      if (type === 'text') label = text(part.body, 2000);
      else if (type === 'button') label = text(part.text || part.payload, 2000);
      else if (type === 'interactive' && isObj(m.interactive)) {
        const reply = isObj(m.interactive.button_reply) ? m.interactive.button_reply : (isObj(m.interactive.list_reply) ? m.interactive.list_reply : {});
        label = text(reply.title, 2000);
      }
      const caption = type === 'text' ? '' : text(part.caption, 500);
      const body_text = label || `[WhatsApp ${type} received]${caption ? `: ${caption}` : ''}`;

      const ts = Number(m.timestamp);
      const contact = contacts.find((c) => String(c.wa_id || '') === from) || (contacts.length === 1 ? contacts[0] : null);
      events.push({
        phone_number_id: pid,
        from,
        sender_name: contact && isObj(contact.profile) ? line(contact.profile.name, 100) : '',
        wa_message_id: id,
        msg_timestamp: Number.isFinite(ts) && ts > 0 ? Math.floor(ts) : nowSec,
        msg_type: type,
        body_text,
        enquiry_text: label.slice(0, 1000),
      });
    }
  }
}

if (events.length) return done('message');
if (rejected.length) return done('ignored');
return done(statuses ? 'status' : 'ignored');

// One item per inbound message (Meta may batch several in one webhook). The next node processes them ONE AT A TIME,
// so two messages from the same new patient can never create two leads, and Lead_ids stay unique inside a batch.
const out = [];
$input.all().forEach((item, i) => {
  const { events, rejected, statuses_seen, http_status, response_body, reject_reason, kind, ...ctx } = item.json;
  for (const ev of events || []) out.push({ json: { ...ctx, ...ev }, pairedItem: { item: i } });
});
return out;

// phone_number_id -> clinic. The Agency Registry table Clinics is small, so it is read whole and matched here as TEXT
// (a Grist column holding the id as a number or as text both work). Active may come back as true or the string "TRUE".
const ctx = $('W2 – Loop Over Messages').item.json;
const rows = Array.isArray($json.records) ? $json.records : [];
const want = String(ctx.phone_number_id || '').trim();
const rec = rows.find((r) => r && r.fields && String(r.fields.WA_Phone_Number_ID === undefined || r.fields.WA_Phone_Number_ID === null ? '' : r.fields.WA_Phone_Number_ID).trim() === want);
const f = rec ? rec.fields : {};
const active = !!rec && String(f.Active).toUpperCase() === 'TRUE';
const doc = rec ? String(f.Grist_Doc_ID || '').trim() : '';
let reason = '';
if (!want) reason = 'no phone_number_id';
else if (!rec) reason = 'unknown phone_number_id';
else if (!active) reason = 'clinic is not active';
else if (!doc) reason = 'clinic has no Grist_Doc_ID';
return {
  json: {
    ...ctx,
    clinic_found: reason === '',
    clinic_reject_reason: reason,
    clinic_slug: rec ? String(f.Clinic_Slug || '') : '',
    clinic_name: rec ? String(f.Clinic_Name || '') : '',
    doc_id: reason === '' ? doc : '',
    wa_phone_number_id: want,
  },
};

// Pasted from n8n/snippets/normalize-phone.js (the same function W12 uses) - keep identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

// WhatsApp gives the sender as digits with the country code (919000000011). Store ONE form only: +91XXXXXXXXXX (CLAUDE.md rule 7).
const { phone, valid } = normalizeIndianPhone($json.from);
return {
  json: {
    ...$json,
    patient_phone: phone,
    phone_valid: valid,
    run_outcome: valid ? '' : 'skipped',
    run_error: valid ? '' : 'sender number is not a valid Indian mobile (+91XXXXXXXXXX); nothing was stored',
  },
};

// Has this WA_Message_ID been stored before? Meta retries deliveries, so the same id can arrive twice.
const ctx = $('W2 – Normalize Phone').item.json;
const rows = Array.isArray($json.records) ? $json.records : [];
const dup = rows.length > 0;
return {
  json: {
    ...ctx,
    is_duplicate: dup,
    run_outcome: dup ? 'skipped' : '',
    run_error: dup ? `duplicate WA_Message_ID (Messages row ${rows[0].id}); nothing was created` : '',
  },
};

const ctx = $('W2 – Read Duplicate').item.json;
const rec = Array.isArray($json.records) ? $json.records[0] : null;
return {
  json: {
    ...ctx,
    lead_found: !!rec,
    lead_row_id: rec ? rec.id : 0,
    lead_id: rec ? String((rec.fields || {}).Lead_id || `row ${rec.id}`) : '',
    lead_created: false,
  },
};

// Same Lead_id rule as W1: L-YYYYMMDD-NNNN (IST date, next free number of the day, read from the 200 newest leads).
const ctx = $('W2 – Read Lead').item.json;
const now = Date.now();
const ymd = new Date(now + 5.5 * 3600 * 1000).toISOString().slice(0, 10).replace(/-/g, '');   // IST date
const prefix = `L-${ymd}-`;
let max = 0;
for (const r of $json.records || []) {
  const id = String((r.fields || {}).Lead_id || '');
  if (id.startsWith(prefix)) max = Math.max(max, parseInt(id.slice(prefix.length), 10) || 0);
}
const lead_id = prefix + String(max + 1).padStart(4, '0');
const fields = {
  Lead_id: lead_id,
  Created_At: Math.floor(now / 1000),                                   // Grist DateTime = epoch seconds
  Name: ctx.sender_name || ctx.default_lead_name || 'WhatsApp Lead',
  Phone: ctx.patient_phone,
  Source: 'WhatsApp',
  Status: 'New',
};
if (ctx.enquiry_text) fields.Enquiry = ctx.enquiry_text;                // only when the patient wrote text
return { json: { ...ctx, new_lead_id: lead_id, create: { records: [{ fields }] } } };

// Race guard. Two messages from the same NEW patient can arrive in parallel (two executions), and both would create a lead.
// After creating, look again: whoever sees several leads for this phone uses the LOWEST row id, so both runs end up on the same lead.
// The extra row is left for staff to delete (W2 never deletes) and is named in the Run_Log note.
const ctx = $('W2 – Build New Lead').item.json;
const made = $('W2 – Create Lead').item.json;
const madeId = made && Array.isArray(made.records) && made.records[0] ? Number(made.records[0].id) : 0;
const rows = (Array.isArray($json.records) ? $json.records : []).filter((r) => r && Number.isInteger(r.id)).sort((a, b) => a.id - b.id);
const canon = rows[0] || (madeId ? { id: madeId, fields: { Lead_id: ctx.new_lead_id } } : null);
const race = !!canon && madeId > 0 && canon.id !== madeId;
const notes = Array.isArray(ctx.race_notes) ? ctx.race_notes.slice() : [];
if (race) notes.push(`parallel messages created lead row ${madeId} as a duplicate of row ${canon.id}; row ${canon.id} is used (row ${madeId} can be deleted)`);
return {
  json: {
    ...ctx,
    lead_found: false,
    lead_row_id: canon ? canon.id : 0,
    lead_id: canon ? String((canon.fields || {}).Lead_id || ctx.new_lead_id) : '',
    lead_created: !!canon && !race,
    race_notes: notes,
    run_outcome: canon ? '' : 'failed',
    run_error: canon ? '' : 'the lead was not found after it was created; message not stored',
  },
};

const ctx = $('W2 – Lead Ready').item.json;
const rows = (Array.isArray($json.records) ? $json.records : []).filter((r) => r && Number.isInteger(r.id)).sort((a, b) => a.id - b.id);
const conv = rows[0] || null;                                           // several rows for one phone: the oldest wins
const f = conv ? conv.fields || {} : {};
return {
  json: {
    ...ctx,
    conversation_found: !!conv,
    conversation_id: conv ? conv.id : 0,
    conversation_created: false,
    conv_unread: Number(f.Unread) || 0,
    conv_last_inbound: Number(f.Last_Inbound_At) || 0,
  },
};

// Same race guard as for leads: after creating, the lowest conversation row id for this phone is the one everybody uses.
const ctx = $('W2 – Read Conversation').item.json;
const made = $('W2 – Create Conversation').item.json;
const madeId = made && Array.isArray(made.records) && made.records[0] ? Number(made.records[0].id) : 0;
const rows = (Array.isArray($json.records) ? $json.records : []).filter((r) => r && Number.isInteger(r.id)).sort((a, b) => a.id - b.id);
const conv = rows[0] || (madeId ? { id: madeId, fields: {} } : null);
const f = conv ? conv.fields || {} : {};
const race = !!conv && madeId > 0 && conv.id !== madeId;
const notes = Array.isArray(ctx.race_notes) ? ctx.race_notes.slice() : [];
if (race) notes.push(`parallel messages created conversation row ${madeId} as a duplicate of row ${conv.id}; row ${conv.id} is used (row ${madeId} can be deleted)`);
return {
  json: {
    ...ctx,
    conversation_found: false,
    conversation_id: conv ? conv.id : 0,
    conversation_created: !!conv && !race,
    conv_unread: Number(f.Unread) || 0,
    conv_last_inbound: Number(f.Last_Inbound_At) || 0,
    race_notes: notes,
    run_outcome: conv ? '' : 'failed',
    run_error: conv ? '' : 'the conversation was not found after it was created; message not stored',
  },
};

// The Messages row exists. Work out the conversation update: Last_Inbound_At never moves backwards (messages can arrive out of order),
// Unread counts up by one (grist/schema.md: Integer) - or becomes true when unread_mode is 'flag' (a Toggle column).
// This runs only for a NEW WA_Message_ID (duplicates stop earlier), so Unread can never be counted twice for one message.
const ctx = $('W2 – Conversation Ready').item.json;
const rec = Array.isArray($json.records) ? $json.records[0] : null;
const unread = ctx.unread_mode === 'flag' ? true : (Number(ctx.conv_unread) || 0) + 1;
const lastInbound = Math.max(Number(ctx.conv_last_inbound) || 0, ctx.msg_timestamp);
return {
  json: {
    ...ctx,
    message_row_id: rec ? Number(rec.id) || 0 : 0,
    conv_update: { records: [{ id: ctx.conversation_id, fields: { Lead: ctx.lead_row_id, Last_Inbound_At: lastInbound, Unread: unread } }] },
  },
};

// Staff alert for a brand-new lead: the PAYLOAD only. W2 sends nothing and does not call W12 (the one WhatsApp sender).
// decision.send is false on purpose, so even if this item is wired to W12 by mistake nothing is sent. After the merge, a guard node
// must fill decision (owner phone from Settings, TEST_MODE / TEST_PHONE, quiet hours) exactly like W3 does, then call W12.
const ctx = $('W2 – Message Saved').item.json;
const saved = ctx.message_row_id > 0;
let staff_alert = null;
if (ctx.lead_created === true) {
  const name = ctx.sender_name || ctx.default_lead_name || 'WhatsApp Lead';
  const quote = ctx.enquiry_text ? ` - "${ctx.enquiry_text.replace(/\s+/g, ' ').slice(0, 200)}"` : '';
  staff_alert = {
    prepared: true,
    audience: 'staff',
    source_workflow: 'W2-WhatsApp-Inbound',
    template: 'new_lead_staff_alert',                                  // W12's WA_TEMPLATES: clinic_name, lead_name, lead_phone, enquiry
    template_params: { clinic_name: ctx.clinic_name, lead_name: name, lead_phone: ctx.patient_phone, enquiry: ctx.enquiry_text || '' },
    message_text: `New WhatsApp lead (${ctx.clinic_name}): ${name}, ${ctx.patient_phone}${quote}. ${ctx.lead_id}.`,
    wa_phone_number_id: ctx.wa_phone_number_id,
    grist_base_url: ctx.grist_base_url,
    doc_id: ctx.doc_id,
    lead_row_id: ctx.lead_row_id,
    lead_phone: ctx.patient_phone,
    decision: { send: false, to: null, reason: 'W2 standalone: staff alert prepared only, not sent', test_mode: true },
  };
}
return {
  json: {
    ...ctx,
    staff_alert,
    run_outcome: saved ? 'ok' : 'failed',
    run_error: saved ? '' : 'the message insert returned no row id',
  },
};

// W13 was started for this message (it runs on its own; W2 does not wait for it). If starting it failed (wrong ai_workflow_id,
// W13 not saved), the message is still stored: the reason goes to Run_Log and nothing else changes.
const ctx = $('W2 – Prepare Staff Alert').item.json;
const e = $json && $json.error;
return { json: { ...ctx, ai_note: e ? `AI hand-off failed: ${String(e.message || e).replace(/\s+/g, ' ').slice(0, 200)}` : 'AI hand-off started' } };

// The one place that turns any outcome (stored, skipped, failed) into a Run_Log row.
// Input is either (a) a full item with run_outcome / run_error, or (b) the error output of a Grist HTTP node ({ error }), in which case the
// message's context is taken from the nearest earlier stage of THIS message. No phone numbers are written: numbers are masked.
const STAGES = ['W2 – Message Saved', 'W2 – Conversation Ready', 'W2 – Read Created Conversation', 'W2 – Read Conversation', 'W2 – Lead Ready',
  'W2 – Read Created Lead', 'W2 – Read Lead', 'W2 – Read Duplicate', 'W2 – Normalize Phone', 'W2 – Resolve Clinic'];
const from = (name) => { try { return $(name).item.json; } catch (e) { return null; } };   // throws when that stage did not run for this message
const isFull = $json && $json.wa_message_id !== undefined;
const loop = from('W2 – Loop Over Messages');
let ctx = null;
let stage = '';
if (isFull) ctx = $json;
else {
  for (const s of STAGES) {
    const c = from(s);
    if (c && (!loop || c.wa_message_id === loop.wa_message_id)) { ctx = c; stage = s.replace('W2 – ', ''); break; }   // same message id = not left over from an earlier loop round
  }
  if (!ctx) ctx = loop || {};
}

const safe = (v, max) => String(v === undefined || v === null ? '' : v).replace(/bearer\s+\S+/gi, 'bearer [hidden]').replace(/\s+/g, ' ').trim().slice(0, max);
const failedHttp = !isFull;
const outcome = failedHttp ? 'failed' : (ctx.run_outcome || 'ok');
let err;
if (failedHttp) {
  const e = $json && $json.error;
  const msg = safe(e && typeof e === 'object' ? (e.message || e.description || JSON.stringify(e)) : e, 300) || 'unknown error';
  err = `Grist request failed${stage ? ` after "${stage}"` : ''}: ${msg}`;
} else if (outcome === 'ok' && Array.isArray(ctx.race_notes) && ctx.race_notes.length) err = ctx.race_notes.join('; ');
else err = ctx.run_error || '';
if (/failed/.test(String(ctx.ai_note || ''))) err = [err, ctx.ai_note].filter(Boolean).join('; ');   // the message is stored; only the AI step failed

const mask = (p) => String(p || '').replace(/\d(?=\d{4})/g, '*');
const id = ctx.wa_message_id || '';
const record = !failedHttp && outcome === 'ok'
  ? `${ctx.lead_id || 'lead'} ${id} (${ctx.lead_created ? 'new lead' : 'existing lead'}, ${ctx.msg_type || 'message'})`
  : `${id} ${mask(ctx.patient_phone || ctx.from)}`.trim();

return {
  json: {
    can_log: !!(ctx.grist_base_url && ctx.doc_id),                      // no clinic resolved = no CRM to log into
    grist_base_url: ctx.grist_base_url,
    doc_id: ctx.doc_id,
    log: { Workflow: 'W2-WhatsApp-Inbound', Record: safe(record, 200), Outcome: outcome, Error: safe(err, 500), At: Math.floor(Date.now() / 1000) },
    outcome,
    wa_message_id: id,
    lead_row_id: ctx.lead_row_id || 0,
    conversation_id: ctx.conversation_id || 0,
    message_row_id: ctx.message_row_id || 0,
    staff_alert: ctx.staff_alert || null,
    ai_handoff: ctx.ai_note || '',
    test_case: ctx.test_case,
  },
};
